rollback.sql:
DELETE FROM krrg_location_states WHERE code IN (
    'AU','AT','AZ','AL','DZ','AR','AM','BY','BE','BG','BR','GB','HU','VN','DE','GR','GE','DK','EG','IL','IN','ID','IE','IS','ES','IT','KZ','CA','CY','CN','KR','LV','LT','LU','MY','MT','MX','MD','NL','NO','AE','PL','PT','RU','RO','SA','RS','SG','SK','SI','US','TH','TR','UZ','UA','FI','FR','HR','CZ','CL','CH','SE','EE','ZA','JP'
);

changeSet.sql:
-- РФ: областные центры (включая Москву и Санкт-Петербург) INSERT INTO krrg_location_cities (name, state_id, created_at, updated_at) SELECT v.name, s.id, now(), now() FROM (VALUES ('Москва'), ('Санкт-Петербург'), ('Абакан'), ('Барнаул'), ('Белгород'), ('Благовещенск'), ('Брянск'), ('Великий Новгород'), ('Владивосток'), ('Владикавказ'), ('Владимир'), ('Волгоград'), ('Вологда'), ('Воронеж'), ('Грозный'), ('Екатеринбург'), ('Иваново'), ('Ижевск'), ('Иркутск'), ('Йошкар-Ола'), ('Казань'), ('Калининград'), ('Калуга'), ('Кемерово'), ('Киров'), ('Кострома'), ('Краснодар'), ('Красноярск'), ('Курган'), ('Курск'), ('Кызыл'), ('Липецк'), ('Магадан'), ('Магас'), ('Махачкала'), ('Мурманск'), ('Нальчик'), ('Нижний Новгород'), ('Новосибирск'), ('Омск'), ('Орел'), ('Оренбург'), ('Пенза'), ('Пермь'), ('Петрозаводск'), ('Псков'), ('Ростов-на-Дону'), ('Рязань'), ('Салехард'), ('Самара'), ('Саратов'), ('Смоленск'), ('Ставрополь'), ('Сыктывкар'), ('Тамбов'), ('Тверь'), ('Томск'), ('Тула'), ('Тюмень'), ('Улан-Удэ'), ('Ульяновск'), ('Уфа'), ('Хабаровск'), ('Ханты-Мансийск'), ('Чебоксары'), ('Челябинск'), ('Черкесск'), ('Чита'), ('Элиста'), ('Южно-Сахалинск'), ('Якутск'), ('Ярославль') ) AS v(name) CROSS JOIN krrg_location_states s WHERE s.code = 'RU' AND NOT EXISTS ( SELECT 1 FROM krrg_location_cities c WHERE c.name = v.name AND c.state_id = s.id );
-- Беларусь: областные центры INSERT INTO krrg_location_cities (name, state_id, created_at, updated_at) SELECT v.name, s.id, now(), now() FROM (VALUES ('Минск'), ('Брест'), ('Витебск'), ('Гомель'), ('Гродно'), ('Могилев') ) AS v(name) CROSS JOIN krrg_location_states s WHERE s.code = 'BY' AND NOT EXISTS ( SELECT 1 FROM krrg_location_cities c WHERE c.name = v.name AND c.state_id = s.id );
-- Европа: столицы (для стран, которые есть в krrg_location_states) INSERT INTO krrg_location_cities (name, state_id, created_at, updated_at) SELECT v.name, s.id, now(), now() FROM (VALUES ('Вена', 'AT'), ('Тирана', 'AL'), ('Минск', 'BY'), ('Брюссель', 'BE'), ('София', 'BG'), ('Лондон', 'GB'), ('Будапешт', 'HU'), ('Берлин', 'DE'), ('Афины', 'GR'), ('Копенгаген', 'DK'), ('Дублин', 'IE'), ('Рейкьявик', 'IS'), ('Мадрид', 'ES'), ('Рим', 'IT'), ('Рига', 'LV'), ('Вильнюс', 'LT'), ('Люксембург', 'LU'), ('Валлетта', 'MT'), ('Кишинев', 'MD'), ('Амстердам', 'NL'), ('Осло', 'NO'), ('Варшава', 'PL'), ('Лиссабон', 'PT'), ('Бухарест', 'RO'), ('Белград', 'RS'), ('Братислава', 'SK'), ('Любляна', 'SI'), ('Киев', 'UA'), ('Хельсинки', 'FI'), ('Париж', 'FR'), ('Загреб', 'HR'), ('Прага', 'CZ'), ('Берн', 'CH'), ('Стокгольм', 'SE'), ('Таллин', 'EE') ) AS v(name, state_code) JOIN krrg_location_states s ON s.code = v.state_code WHERE NOT EXISTS ( SELECT 1 FROM krrg_location_cities c WHERE c.name = v.name AND c.state_id = s.id );
